import subprocess
from pathlib import Path

runtime = Path("src/do_again/browser/runtime.py")
tests = Path("tests/test_browser.py")

text = runtime.read_text()
old = '''def _page_contains(target: cdp.Target, text: str) -> bool:
    needle = json.dumps(text)
    expression = (
        "(() => {" + _MESSAGE_NODES_JS + "const users = messageNodes('user'); "
        f"return users.some(el => (el.innerText || '').includes({needle})); }})()"
    )
    return bool(cdp.evaluate(target, expression, timeout=10.0))
'''
new = '''def _page_contains(target: cdp.Target, text: str) -> bool:
    needle = json.dumps(text)
    expression = (
        "(() => {" + _MESSAGE_NODES_JS + r"""
const needle = """ + needle + r""";
const users = messageNodes('user');
if (users.some(el => (el.innerText || el.textContent || '').includes(needle))) return true;
const conversation = document.querySelector('[aria-label="Conversation"]') || document.body;
if (!conversation) return false;
const raw = (conversation.innerText || conversation.textContent || '').replace(/\r\n/g, '\n');
const labeled = 'You said:\n' + needle;
return raw.includes(labeled);
})()"""
    )
    return bool(cdp.evaluate(target, expression, timeout=10.0))
'''
if old not in text:
    raise SystemExit("page_contains block not found")
runtime.write_text(text.replace(old, new))

test_text = tests.read_text()
anchor = '''    def test_duplicate_receipt_marker_is_not_sent_twice(self) -> None:
'''
if anchor not in test_text:
    raise SystemExit("test anchor not found")

insert = '''    def test_page_contains_falls_back_to_current_conversation_user_label(self) -> None:
        target = cdp.Target(
            "target",
            "https://chatgpt.com/c/project",
            "",
            "ws://127.0.0.1/x",
        )
        captured = {}

        def evaluate(_target, expression, **kwargs):
            captured["expression"] = expression
            return True

        with patch("do_again.browser.runtime.cdp.evaluate", side_effect=evaluate):
            self.assertTrue(
                __import__("do_again.browser.runtime", fromlist=["_page_contains"])._page_contains(
                    target,
                    "DO_AGAIN_RECEIPT_READY request_id=req-dup state=",
                )
            )
        self.assertIn("You said:", captured["expression"])
        self.assertIn('aria-label="Conversation"', captured["expression"])

''' + anchor
tests.write_text(test_text.replace(anchor, insert))

subprocess.run(["python3", "-m", "unittest", "tests.test_browser"], check=True)
subprocess.run(["python3", "-m", "unittest", "discover", "-s", "tests", "-p", "test_*.py"], check=True)
subprocess.run(["git", "add", str(runtime), str(tests)], check=True)
subprocess.run(["git", "commit", "-m", "Harden receipt dedupe for current ChatGPT DOM"], check=True)
subprocess.run(["git", "push", "origin", "main"], check=True)
print(subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip())
